  10 import { createContext, ReactNode, useCallback, useContext, useEffect, useState } from 'react';
  11 import { useBuilderStore } from '@/hooks';
  12 
  13 interface AuthContextType {
  14   firebaseUser: FirebaseUser | null;
  15   userProfile: User | null;
  16   isLoading: boolean;
  17   refetchUser: () => void;
  18 }
