  22 // Handles setting/clearing the session cookie.
  23 async function manageSession(user: FirebaseUser | null) {
  24   if (user) {
  25     const idToken = await user.getIdToken(true);
  26     // Set session cookie
  27     await fetch('/api/auth/session', {
  28       method: 'POST',
  29       headers: { 'Content-Type': 'application/json' },
  30       body: JSON.stringify({ idToken }),
  31     });
  32   } else {
  33     // Clear session cookie
  34     await fetch('/api/auth/logout', {
  35       method: 'POST',
  36     });
  37   }
  38 }
  39 
  40 export const AuthProvider = ({ children }: { children: ReactNode }) => {
  41   const [firebaseUser, setFirebaseUser] = useState<FirebaseUser | null>(null);
  42   const [authIsLoading, setAuthIsLoading] = useState(true);
  43   const queryClient = useQueryClient();
  44   const { setUserProfile } = useBuilderStore(); // Get setter from builder store
  45 
  46   useEffect(() => {
  47     if (firebaseUser?.uid) {
  48       const unsubscribe = subscribeToUserProfile(firebaseUser.uid, (user) => {
  49         const userInstance = user ? new User(user) : null;
  50         queryClient.setQueryData(userKeys.profile(firebaseUser.uid), userInstance);
  51         setUserProfile(userInstance); // Update builder store
  52       });
  53       return () => unsubscribe();
  54     } else {
  55       setUserProfile(null); // Clear on logout
  56     }
  57   }, [firebaseUser, queryClient, setUserProfile]);
  58 
  59   // Use React Query to get the user profile from the cache
  60   const { data: userProfile, isLoading: isProfileLoading } = useQuery<User | null>({
  61     queryKey: userKeys.profile(firebaseUser?.uid ?? ''),
  62     queryFn: async () => {
  63       if (!firebaseUser) return null;
  64       const token = await getAuthenticatedToken(firebaseUser);
  65       const userProfileData = await fetchUserProfileApi(firebaseUser.uid, token);
  66       const userInstance = userProfileData ? new User(userProfileData) : null;
  67       setUserProfile(userInstance); // Update builder store on fetch
  68       return userInstance;
  69     },
  70     enabled: !!firebaseUser,
  71     staleTime: Infinity,
  72   });
  73 
  74   const refetchUser = useCallback(() => {
  75     if (firebaseUser?.uid) {
  76       queryClient.invalidateQueries({ queryKey: userKeys.profile(firebaseUser.uid) });
  77     }
  78   }, [firebaseUser, queryClient]);
  79 
  80   useEffect(() => {
  81     const unsubscribe = onAuthStateChanged(auth, async (user) => {
  82       setFirebaseUser(user);
  83       await manageSession(user);
  84       if (user) {
  85         // Invalidate and refetch immediately on auth change
  86         await queryClient.invalidateQueries({ queryKey: userKeys.profile(user.uid) });
  87       } else {
  88         // Clear all queries on logout
  89         queryClient.clear();
  90         setUserProfile(null); // Clear builder store on logout
  91       }
  92       setAuthIsLoading(false);
  93     });
  94 
  95     return () => unsubscribe();
  96   }, [queryClient, setUserProfile]);
  97 
  98   return (
  99     <AuthContext.Provider value={{
 100       firebaseUser,
 101       userProfile: userProfile ?? null,
 102       isLoading: authIsLoading || (!!firebaseUser && isProfileLoading),
 103       refetchUser
 104     }}>
 105       {children}
 106     </AuthContext.Provider>
 107   );
 108 };
 109 
 110 export const useAuth = (): AuthContextType => {
 111   const context = useContext(AuthContext);
 112   if (context === undefined) {
 113     throw new Error('useAuth must be used within an AuthProvider');
 114   }
 115   return context;
 116 };
