   4 
   5 interface ApiServiceOptions<T> {
   6   endpoint: string;
   7   method?: 'GET' | 'POST' | 'PUT' | 'DELETE';
   8   data?: T;
   9   token?: string; // Allow passing token directly
  10   firebaseUser?: FirebaseUser | null; // Or pass the user object
  11   headers?: Record<string, string>;
  12   isFormData?: boolean;
  13 }
  14 
  15 /**
  16  * A unified API service function to handle all client-server communication.
  17  * It automatically handles authentication, request body serialization, and response parsing.
  18  *
  19  * @param options - The configuration for the API request.
  20  * @returns A promise that resolves to the JSON response from the API.
  21  * @throws An error if the request fails or the user is not authenticated when required.
  22  */
  23 export async function apiService<TRequest = any, TResponse = any>(
  24   options: ApiServiceOptions<TRequest>
  25 ): Promise<TResponse> {
  26   const {
  27     endpoint,
  28     method = 'GET',
  29     data,
  30     token: directToken,
  31     firebaseUser,
  32     headers = {},
  33     isFormData = false,
  34   } = options;
  35 
  36   let authToken = directToken;
  37 
  38   if (!authToken && firebaseUser) {
  39     authToken = await getAuthenticatedToken(firebaseUser);
  40   }
  41 
  42   const config: RequestInit = {
  43     method,
  44     headers: { ...headers },
  45   };
  46 
  47   if (authToken) {
  48     config.headers = {
  49       ...config.headers,
  50       'Authorization': `Bearer ${authToken}`,
  51     };
  52   }
  53 
  54   if (data) {
  55     if (isFormData) {
  56       // Don't set Content-Type for FormData, browser does it with boundary
  57       config.body = data as unknown as FormData;
  58     } else {
  59       (config.headers as Record<string, string>)['Content-Type'] = 'application/json';
  60       config.body = JSON.stringify(data);
  61     }
  62   }
  63 
  64   const response = await fetch(endpoint, config);
  65 
  66   if (!response.ok) {
  67     let errorData;
  68     try {
  69       errorData = await response.json();
  70     } catch {
  71       // If the response is not JSON, use the status text
  72       errorData = { message: response.statusText || 'An unknown error occurred.' };
  73     }
  74     throw new Error(errorData.message);
  75   }
  76 
  77   // Handle cases where the response might be empty (e.g., DELETE 204 No Content)
  78   const contentType = response.headers.get('content-type');
  79   if (contentType && contentType.includes('application/json')) {
  80     return response.json();
  81   }
  82   // Return an empty object or a success indicator for non-JSON responses
  83   return {} as TResponse;
  84 }
